callback_with_context.context_function_id:
ritual
| ritual.IsScriptLocked == true =>
(
  threshold = PlayersFaction
    .PooledResourceContext("wh3_dlc29_glott_souls")
    .EffectList("ABSOLUTE_VALUE")
    .Sort(Key, true)
    .FirstContext(
      EffectBundle.EffectsIncludingHiddenList.Any(
        RitualList.Any(Key == ritual.RitualContext.ExRotborneRituals_GetBaseKey)
      )
    )
) =>
{
  Format(
    "{{tr:ui_text_replacements_localised_text_wh3_dlc29_nurgle_marks_threshold_progress_requirement_text}}",
    GetIfElse(IsContextValid(threshold), threshold.LowerBound, 0)
  )
}
| ritual.IsDisabledViaBonusValues == true =>
{
  ritual.RitualContext.DisplayName + "
" + ritual.ExRotborneRituals_NoValidTargetsText
}
| ritual.RitualContext.DisplayName

ritual
| ritual.IsScriptLocked == true =>
(
  threshold = PlayersFaction
    .PooledResourceContext("wh3_dlc29_glott_souls")
    .EffectList("ABSOLUTE_VALUE")
    .Sort(Key, true)
    .FirstContext(
      EffectBundle.EffectsIncludingHiddenList.Any(
        RitualList.Any(Key == ritual.RitualContext.ExRotborneRituals_GetBaseKey)
      )
    )
) =>
{
  Format(
    "{{tr:ui_text_replacements_localised_text_wh3_dlc29_nurgle_marks_threshold_progress_requirement_text}}",
    GetIfElse(IsContextValid(threshold), threshold.LowerBound, 0)
  )
}
| ritual.IsDisabledViaBonusValues == true =>
{
  ritual.RitualContext.DisplayName + "
" + ritual.ExRotborneRituals_NoValidTargetsText
}
| ritual.RitualContext.DisplayName

(
  plague_key_and_setup = "wh3_dlc29_plague_blooming_pox+wh3_dlc29_woc_rotborne_rituals_plague_effects_setup",
  blessed_plague_key_and_setup = "wh3_dlc29_plague_blooming_pox_blessed+wh3_dlc29_woc_rotborne_rituals_plague_effects_setup_blessed"
)
=>
{
GetIfElse(
  EffectKey == "wh3_dlc29_effect_woc_rotborne_rituals_create_plague_dummy",
  FindContext("CcoCampaignBasePlague", plague_key_and_setup).PlagueCompositionContext,
  FindContext("CcoCampaignBasePlague", blessed_plague_key_and_setup).PlagueCompositionContext
)
}

GetIfElse(
  ritual.IsScriptLocked,
  (
    threshold = PlayersFaction
      .PooledResourceContext("wh3_dlc29_glott_souls")
      .EffectList("ABSOLUTE_VALUE")
      .Sort(Key, true)
      .FirstContext(
        EffectBundle.EffectsIncludingHiddenList.Any(
          RitualList.Any(Key == ritual.RitualContext.ExRotborneRituals_GetBaseKey)
        )
      )
  ) =>
  {
    Format(
      "{{tr:ui_text_replacements_localised_text_wh3_dlc29_nurgle_marks_threshold_progress_requirement_text}}",
      GetIfElse(IsContextValid(threshold), threshold.LowerBound, 0)
    )
  },
  ritual.ExRotborneRituals_NoValidTargetsText
)
